// AI generated by: Claude Code / Claude Sonnet 5.5
// Prompt: "implementation done using skill: mattpocock-skills:implement-spec,
// ticket 03: blocks and simple statements"
// Changes: implemented parser_peek: the token after the current one is fetched
// through the token layer (WHITESPACE dropped, raw indents translated) and kept
// until parser_advance moves to it.
const Token* parser_peek(Ctx* ctx, Parser* parser) {
  if (!parser->has_peeked) {
    parser->peeked = fetch_token(ctx, parser);
    parser->has_peeked = true;
  }
  return &parser->peeked;
}

